{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Absolute oral bioavailability of morphine, the closest structural analogue, was 32% in healthy volunteers after immediate-release tablets, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Morphine-d3, a near-isotopic analogue of morphine, had an oral bioavailability of 37.2 ± 10.2% in opioid-dependent patients, supporting high oral availability for the morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Absolute oral morphine bioavailability reached 42.6% in a patient with malignant disease, showing that close analogues can achieve oral F well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Naltrexone, a 6-keto morphinan with N-cyclopropylmethyl and 14-hydroxy substitution, had ~5% oral bioavailability in healthy volunteers; this low value is only weakly transferable because the query lacks those substituents.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 6-keto N-methyl morphinan (hydromorphone-like). The closest analogues, morphine and morphine-d3, show absolute oral bioavailability values mostly between 21% and 51%, with several robust estimates around 32–43%, supporting F ≥ 20%. Low-F naltrexone data are less transferable due to N-cyclopropylmethyl and 14-hydroxy substitution and extensive first-pass metabolism. Overall prediction: high oral bioavailability.",
  "evidence_gaps": [
    "No direct hydromorphone bioavailability record is present in the retrieved evidence set; the prediction relies on close morphinan analogues.",
    "Morphine oral bioavailability estimates vary widely across studies, though most are above the 20% threshold.",
    "Naltrexone low-F records introduce some uncertainty, but structural differences reduce their transferability to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

